package cn.sixnine.filmlog;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.*;import android.location.Location;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public final class PerformanceInstrumentation extends Instrumentation {
 interface Action{void run()throws Exception;} Activity activity;LogStore logs;Context context;Bundle arguments;JSONArray results=new JSONArray();String roll,scan;int violations;JSONArray samples=new JSONArray();final android.os.Handler handler=new android.os.Handler(Looper.getMainLooper());
 static String id(String key){return UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 void main(Action a)throws Exception{Throwable[] error={null};runOnMainSync(()->{try{a.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new RuntimeException(error[0]);}
 Object field(Object o,String n)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}void call(Object o,String n,Class<?>[] types,Object...v)throws Exception{java.lang.reflect.Method m=o.getClass().getDeclaredMethod(n,types);m.setAccessible(true);m.invoke(o,v);}
 void metric(String name,int repeats,boolean ui,Action a)throws Exception{android.util.Log.i("FilmPerf",name);JSONArray values=new JSONArray();for(int i=0;i<repeats;i++){long start=System.nanoTime();if(ui)main(a);else a.run();values.put((System.nanoTime()-start)/1e6);}results.put(new JSONObject().put("name",name).put("ms",values));}
 void drawableBytes(View view,Set<Bitmap> bitmaps){if(view instanceof ImageView&&((ImageView)view).getDrawable() instanceof android.graphics.drawable.BitmapDrawable)bitmaps.add(((android.graphics.drawable.BitmapDrawable)((ImageView)view).getDrawable()).getBitmap());if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)drawableBytes(((ViewGroup)view).getChildAt(i),bitmaps);}
 void settle(){Runtime.getRuntime().gc();SystemClock.sleep(180);Runtime.getRuntime().gc();SystemClock.sleep(180);}
 void closePage()throws Exception{if(activity!=null){final Activity closing=activity;main(()->closing.finish());for(int i=0;i<150&&!closing.isDestroyed();i++)SystemClock.sleep(20);check(closing.isDestroyed(),"activity destroyed before workspace change");activity=null;}}
 void startPage(Class<?> type,Intent intent)throws Exception{closePage();activity=startActivitySync(intent.setClass(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();}
 void render(String screen)throws Exception{main(()->{set(activity,"screen",screen);call(activity,"render",new Class<?>[]{});});}
 void seed(int count,int frames,int images)throws Exception{SQLiteDatabase db=logs.getWritableDatabase();roll=id("perf-roll-0");try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM rolls",null)){c.moveToFirst();if(c.getInt(0)>0)return;}
  File dir=new File(context.getFilesDir(),"scans");dir.mkdirs();File original=new File(context.getFilesDir(),"perf-source.jpg");Bitmap b=Bitmap.createBitmap(4000,3000,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint p=new Paint();for(int y=0;y<3000;y+=40)for(int x=0;x<4000;x+=40){p.setColor(0xff000000|((x*73+y*37)&0xffffff));canvas.drawRect(x,y,x+40,y+40,p);}try(OutputStream out=new FileOutputStream(original)){b.compress(Bitmap.CompressFormat.JPEG,94,out);}b.recycle();byte[] bytes=java.nio.file.Files.readAllBytes(original.toPath());java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");StringBuilder sha=new StringBuilder();for(byte v:hash.digest(bytes))sha.append(String.format(Locale.ROOT,"%02x",v&255));
  db.beginTransaction();try{for(int i=0;i<count;i++){String rid=id("perf-roll-"+i);db.execSQL("INSERT INTO rolls(id,name,stock,camera,iso,capacity,created_at,state) VALUES(?,?,?,?,?,?,?,?)",new Object[]{rid,"性能测试 "+i,"Kodak Ultramax 400","Nikon FE2",400,36,1780000000000L+i*1000,i<3?"active":"received"});for(int j=1;j<=(i==0?frames:36);j++){String sid=id("perf-shot-"+i+"-"+j);long tap=1780000000000L+i*100000+j*1000;db.execSQL("INSERT INTO shots(id,roll_id,frame_number,tapped_at,captured_at,offset_seconds,zone_offset_minutes,status,latitude,longitude,accuracy_m,location_time,provider,aperture,shutter,memo) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",new Object[]{sid,rid,j,tap,tap-10000,-10,480,"acquired",31.2,121.4,15,tap,"gps","8","1/125","测试 "+j});if(i==0&&j<=images){String img=id("perf-scan-"+j);if(j==1)scan=img;java.nio.file.Files.write(new File(dir,img+".jpg").toPath(),bytes);db.execSQL("INSERT INTO scans(id,roll_id,display_name,sha256,byte_count,created_at,shot_id) VALUES(?,?,?,?,?,?,?)",new Object[]{img,rid,"scan-"+j+".jpg",sha.toString(),bytes.length,tap,sid});}}ArtworkLinks.put(db,"roll",rid,"original:kodak_ultramax_400");}db.setTransactionSuccessful();}finally{db.endTransaction();}
 }
 void profile(String size,int count,int frames,int images)throws Exception{closePage();Workspace.activate(getTargetContext(),id("performance-20261028-"+size));context=Workspace.context(getTargetContext());logs=new LogStore(context);seed(count,frames,images);roll=id("perf-roll-0");scan=id("perf-scan-1");results.put(new JSONObject().put("dataset",size).put("rolls",count).put("shots",(count-1)*36+frames).put("target_frames",frames).put("photos",images).put("jpeg_dimensions","4000x3000").put("jpeg_bytes",new File(context.getFilesDir(),"perf-source.jpg").length()));
  metric(size+".roll.lookup100",5,false,()->{for(int i=0;i<100;i++)check(logs.roll(id("perf-roll-"+(i%count))).count>0,"roll");});metric(size+".rolls.aggregate",5,false,()->logs.rolls());metric(size+".home.summary",5,false,()->HomeCards.read(logs));metric(size+".search.memo",3,false,()->ManagementStore.search(logs,"测试",new ManagementStore.Criteria(),false));
  long start=System.nanoTime();startPage(MainActivity.class,new Intent());results.put(new JSONObject().put("name",size+".activity.first").put("ms",new JSONArray().put((System.nanoTime()-start)/1e6)));
  main(()->{StrictMode.setThreadPolicy(new StrictMode.ThreadPolicy.Builder().detectDiskReads().detectDiskWrites().penaltyListener(Runnable::run,v->{violations++;if(samples.length()<12)samples.put(v.toString());}).build());});
  metric(size+".dashboard.render",3,true,()->{set(activity,"screen","dashboard");call(activity,"render",new Class<?>[]{});});metric(size+".list.render",3,true,()->{set(activity,"screen","home");call(activity,"render",new Class<?>[]{});});metric(size+".roll.open",3,true,()->{set(activity,"rollId",roll);set(activity,"screen","roll");call(activity,"render",new Class<?>[]{});});
  final ArrayList<Long> framesMs=new ArrayList<>();Window.OnFrameMetricsAvailableListener listener=(w,m,d)->{synchronized(framesMs){framesMs.add(m.getMetric(FrameMetrics.TOTAL_DURATION));}};main(()->activity.getWindow().addOnFrameMetricsAvailableListener(listener,handler));
  for(int i=0;i<25;i++){final int y=i%2==0?i*100:Math.max(0,(i-2)*100);main(()->((ScrollView)field(activity,"pageScroll")).smoothScrollTo(0,y));SystemClock.sleep(35);}SystemClock.sleep(300);main(()->activity.getWindow().removeOnFrameMetricsAvailableListener(listener));JSONArray fm=new JSONArray();synchronized(framesMs){for(long v:framesMs)fm.put(v/1e6);}results.put(new JSONObject().put("name",size+".roll.scroll.frames").put("ms",fm));
  metric(size+".editor.open",3,true,()->{set(activity,"shotId","");call(activity,"editShot",new Class<?>[]{String.class},id("perf-shot-0-1"));});
  metric(size+".record.located",5,false,()->{Location fix=new Location("gps");fix.setLatitude(31.2);fix.setLongitude(121.4);fix.setAccuracy(15);fix.setTime(System.currentTimeMillis());fix.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());String sid=logs.recordLocated(UUID.randomUUID().toString(),id("perf-roll-2"),System.currentTimeMillis(),-10,480,"8","1/125","","","","",fix);LogStore.Shot s=logs.shot(sid);check(s.lat!=null&&s.captured==s.tapped-10000,"time and GPS");logs.getWritableDatabase().delete("shots","id=?",new String[]{sid});});
  closePage();settle();start=System.nanoTime();startPage(ScansActivity.class,new Intent().putExtra("roll",roll));results.put(new JSONObject().put("name",size+".scans.open").put("ms",new JSONArray().put((System.nanoTime()-start)/1e6)));SystemClock.sleep(2200);settle();final Set<Bitmap> rendered=new HashSet<>();main(()->drawableBytes(activity.findViewById(android.R.id.content),rendered));long drawableBytes=0;for(Bitmap bitmap:rendered)drawableBytes+=bitmap.getAllocationByteCount();results.put(new JSONObject().put("name",size+".scans.drawable_bitmaps").put("count",rendered.size()).put("bytes",drawableBytes));rendered.clear();results.put(new JSONObject().put("name",size+".scans.heap").put("java_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory()).put("native_bytes",Debug.getNativeHeapAllocatedSize()));
  closePage();startPage(ScanViewerActivity.class,new Intent().putExtra("viewer_roll",roll).putExtra("scan",scan));SystemClock.sleep(500);metric(size+".viewer.next",10,true,()->call(activity,"load",new Class<?>[]{int.class},((Integer)field(activity,"position")+1)%images));SystemClock.sleep(1200);closePage();
  final File backup=new File(context.getCacheDir(),"perf-backup.zip");startPage(BackupActivity.class,new Intent());final long[] gap={0},last={SystemClock.uptimeMillis()};final boolean[] running={true};Runnable heartbeat=new Runnable(){public void run(){long now=SystemClock.uptimeMillis();gap[0]=Math.max(gap[0],now-last[0]);last[0]=now;if(running[0])handler.postDelayed(this,16);}};handler.post(heartbeat);metric(size+".backup.write",1,false,()->{try(OutputStream out=new FileOutputStream(backup)){FilmBackup.write(context,logs,out);}});metric(size+".backup.inspect",1,false,()->{try(InputStream in=new FileInputStream(backup);FilmBackup.Prepared prepared=FilmBackup.inspect(context,in)){check(prepared.count("shots")==count*36+(frames-36),"backup count");}});running[0]=false;main(()->handler.removeCallbacks(heartbeat));results.put(new JSONObject().put("name",size+".backup.responsiveness").put("heartbeat_max_gap_ms",gap[0]).put("zip_bytes",backup.length()));backup.delete();closePage();logs.close();
 }
 Button named(View view,String prefix){if(view instanceof Button&&((Button)view).getText().toString().startsWith(prefix))return (Button)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){Button b=named(((ViewGroup)view).getChildAt(i),prefix);if(b!=null)return b;}return null;}
 void awaitJob(boolean backup)throws Exception{long end=SystemClock.uptimeMillis()+120000;while(true){boolean[] busy={true};main(()->busy[0]=backup?(Boolean)field(field(activity,"state"),"busy"):(Boolean)field(activity,"busy"));if(!busy[0])return;if(SystemClock.uptimeMillis()>end)throw new AssertionError("job timeout");SystemClock.sleep(25);}}
 void jobs()throws Exception{
  Workspace.activate(getTargetContext(),id("performance-20261028-large"));Context large=Workspace.context(getTargetContext());File source=new File(large.getFilesDir(),"perf-source.jpg");check(source.isFile(),"existing12MP fixture");byte[] original=java.nio.file.Files.readAllBytes(source.toPath());
  final long[] gap={0},last={SystemClock.uptimeMillis()};final boolean[] running={true};Runnable heartbeat=new Runnable(){public void run(){long now=SystemClock.uptimeMillis();gap[0]=Math.max(gap[0],now-last[0]);last[0]=now;if(running[0])handler.postDelayed(this,16);}};handler.post(heartbeat);
  try{
   startPage(BackupActivity.class,new Intent());File zip=new File(large.getCacheDir(),"perf-real-ui.zip");metric("jobs.backup.ui_export",1,false,()->{main(()->call(activity,"onActivityResult",new Class<?>[]{int.class,int.class,Intent.class},1,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(zip))));awaitJob(true);});check(zip.length()>0,"export bytes");
   metric("jobs.backup.ui_inspect",1,false,()->{main(()->call(activity,"onActivityResult",new Class<?>[]{int.class,int.class,Intent.class},2,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(zip))));awaitJob(true);});Object prepared=field(field(activity,"state"),"prepared");check(prepared!=null,"inspect prepared");
   closePage();Workspace.activate(getTargetContext(),UUID.randomUUID().toString());Context restored=Workspace.context(getTargetContext());startPage(BackupActivity.class,new Intent());final FilmBackup.Prepared restoreInput;try(InputStream in=new FileInputStream(zip)){restoreInput=FilmBackup.inspect(restored,in);}main(()->set(field(activity,"state"),"prepared",restoreInput));metric("jobs.backup.ui_restore",1,false,()->{main(()->call(activity,"restore",new Class<?>[]{}));awaitJob(true);});try(LogStore target=new LogStore(restored)){check(target.rolls().size()==400,"restore400 rolls");try(Cursor c=target.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM shots",null)){c.moveToFirst();check(c.getInt(0)==14724,"restore14724 shots");}check(new ScanStore(restored,target).list(target.rolls().get(target.rolls().size()-1).id)!=null,"restored images valid");}
   closePage();zip.delete();
   for(int count:new int[]{12,120}){Workspace.activate(getTargetContext(),UUID.randomUUID().toString());Context c=Workspace.context(getTargetContext());try(LogStore db=new LogStore(c)){String r=db.addRoll("Import benchmark "+count,"Test","",400,36);ArrayList<android.net.Uri> uris=new ArrayList<>();for(int i=0;i<count;i++)uris.add(android.net.Uri.fromFile(source));startPage(ScansActivity.class,new Intent().putExtra("roll",r));metric("jobs.import"+count+".stage_preview",1,false,()->{main(()->call(activity,"stageSources",new Class<?>[]{ArrayList.class},uris));awaitJob(false);});check(ImportQueue.previews(db,r).size()==count,"preview count");metric("jobs.import"+count+".confirm_until_complete",1,false,()->{main(()->{Button commit=named(activity.findViewById(android.R.id.content),"确认导入");check(commit!=null,"confirm exists");commit.performClick();});awaitJob(false);});ArrayList<ScanStore.Scan> scans=new ScanStore(c,db).list(r);check(scans.size()==count,"all originals imported");for(ScanStore.Scan scan:scans)check(java.util.Arrays.equals(original,java.nio.file.Files.readAllBytes(new ScanStore(c,db).file(scan.id).toPath())),"original JPEG bytes retained");closePage();}}
   Workspace.activate(getTargetContext(),UUID.randomUUID().toString());Context c=Workspace.context(getTargetContext());logs=new LogStore(c);String owner=logs.addRoll("reference save","Test","",400,36);Bitmap image=Bitmap.createBitmap(1280,1280,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);Paint paint=new Paint();for(int y=0;y<1280;y+=10){paint.setColor(0xff000000|(y*137));canvas.drawRect(0,y,1280,y+10,paint);}boolean asynchronous;try{MeterActivity.class.getDeclaredMethod("saveReference",Intent.class,String.class,Bitmap.class);asynchronous=true;}catch(NoSuchMethodException oldVersion){asynchronous=false;}metric(asynchronous?"jobs.reference1280.capture_background":"jobs.reference1280.capture_main",3,!asynchronous,()->{String token=UUID.randomUUID().toString();ReferencePhotos.capture(c,token,image);ReferencePhotos.discard(c,token);});image.recycle();logs.close();logs=null;
  }finally{running[0]=false;main(()->handler.removeCallbacks(heartbeat));results.put(new JSONObject().put("name","jobs.ui_heartbeat").put("max_gap_ms",gap[0]));check(Arrays.equals(original,java.nio.file.Files.readAllBytes(source.toPath())),"input unchanged");closePage();}
 }
 @Override public void onCreate(Bundle args){super.onCreate(args);arguments=args==null?new Bundle():args;start();}
 @Override public void onStart(){Bundle out=new Bundle();boolean ok=false;String previous=Workspace.current(getTargetContext());try{check(getTargetContext().getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolation");if(Boolean.parseBoolean(arguments.getString("jobs","false")))jobs();else{profile("small",12,36,12);profile("large",400,360,120);}results.put(new JSONObject().put("strictmode_disk_events",violations).put("examples",samples));File output=new File(getTargetContext().getFilesDir(),"performance-"+arguments.getString("label","baseline")+".json");try(Writer w=new FileWriter(output)){w.write(results.toString(2));}out.putString("stream","PASS performance measurements: "+output+"\n"+results.toString()+"\n");ok=true;}catch(Throwable t){out.putString("stream",android.util.Log.getStackTraceString(t));}finally{try{main(()->StrictMode.setThreadPolicy(StrictMode.ThreadPolicy.LAX));closePage();if(logs!=null)logs.close();}catch(Exception ignored){}}finish(ok?-1:0,out);}
}
